"""Render readable vector figures and the final automated results report."""
import argparse,json,sys
from pathlib import Path
BASE=Path(__file__).resolve().parent
ap=argparse.ArgumentParser();ap.add_argument('--packages',type=Path,required=True);a=ap.parse_args();sys.path.insert(0,str(a.packages.resolve()))
import numpy as np,matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.ticker import FixedLocator,FuncFormatter,NullLocator
OUT=BASE/'results/final-automated-analysis-v0.7';models=json.loads((OUT/'models.json').read_text());support=json.loads((OUT/'support.json').read_text());sens=json.loads((OUT/'sensitivity.json').read_text());logistic=json.loads((OUT/'logistic-sensitivity.json').read_text())
NAMES={'odoo__odoo':'Odoo','jenkinsci__jenkins':'Jenkins','apache__tomcat':'Tomcat'};RULES={'LongMethod':'Long Method','GodClass':'God Class','ObsoleteApiUsage':'Source-declared obsolete API'}
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':9,'pdf.fonttype':42,'svg.fonttype':'none'})
for endpoint,filename,label,null in [('binary','adjusted-change-probability','Adjusted difference in change probability (percentage points)',0),('count','adjusted-change-count','Adjusted mean change-count ratio',1)]:
 fig,axes=plt.subplots(1,3,figsize=(11.4,3.5),layout='constrained')
 for ax,rule in zip(axes,RULES):
  ax.axvline(null,color='0.6',linewidth=.8,linestyle='--')
  for i,rid in enumerate(NAMES):
   r=next(r for r in models if r['repository']==rid and r['rule']==rule and r['endpoint']==endpoint)
   if r['status']=='fitted':
    value=r['effect'];lo=r.get('ci_low');hi=r.get('ci_high')
    if lo is not None and np.isfinite([lo,hi]).all():ax.errorbar(value,i,xerr=[[value-lo],[hi-value]],fmt='o',color='#245b78',capsize=3,markersize=5)
    else:ax.plot(value,i,'o',color='#245b78')
   else:ax.text(.98,i,'Descriptive only',ha='right',va='center',transform=ax.get_yaxis_transform(),fontsize=8,color='0.45')
  if endpoint=='count':
   ax.set_xscale('log');ticks={'LongMethod':[.95,1,1.05,1.1,1.15,1.2],'GodClass':[1,1.1,1.2,1.3],'ObsoleteApiUsage':[.3,.5,1,2,3]}[rule]
   ax.xaxis.set_major_locator(FixedLocator(ticks));ax.xaxis.set_major_formatter(FuncFormatter(lambda x,pos:f'{x:g}'));ax.xaxis.set_minor_locator(NullLocator())
  ax.set_yticks(range(3),list(NAMES.values()));ax.set_ylim(2.6,-.6);ax.set_title(RULES[rule]);ax.grid(axis='x',alpha=.15);ax.spines[['top','right']].set_visible(False)
 fig.supxlabel(label);fig.savefig(OUT/(filename+'.pdf'),metadata={'CreationDate':None,'ModDate':None});fig.savefig(OUT/(filename+'.png'),dpi=180);plt.close(fig)

def model(rid,rule,endpoint):return next(r for r in models if r['repository']==rid and r['rule']==rule and r['endpoint']==endpoint)
lines=['# Final automated analysis: anti-patterns and subsequent file changes','','## Finding','','The clearest adjusted association concerns change frequency in files flagged for God Class. In the supported comparison populations, the adjusted mean count ratio is 1.223 for Jenkins (95% interval 1.132–1.321) and 1.142 for Tomcat (1.023–1.275). These correspond to approximately 22% and 14% more recorded changes over the following 365 days. The association is similar when counting modifications alone. These are secondary count results with unadjusted 95% intervals; they must not be presented as the result of the main multiplicity-controlled test.','', 'The main endpoint—whether any recorded change occurs—does not provide clear evidence of an adjusted association for any fitted contrast: all seven main intervals include zero, and none passes the Holm-adjusted 5% threshold. This is not evidence that the anti-patterns have no effect. The estimates concern recorded changes, and several are imprecise.','','## Scope and authorisation','','The user explicitly waived independent human validation. This is the completed automated analysis under amendment v0.7; human labels are not required to release these results. The underlying detector decisions remain unreviewed. The original confirmed-corrective-maintenance outcome was not measured: file-change activity, previously a secondary endpoint, is the reported endpoint here. No blank corrective label was interpreted as non-corrective.','', 'Long Method denotes a named definition with cyclomatic complexity greater than 10. God Class requires ATFD > 4, WMC ≥ 47 and TCC < 1/3 jointly. Obsolete API Usage concerns resolved references to APIs deprecated within the same source snapshot. The file-level exposure is the presence of at least one such finding; these operational definitions are not interchangeable with all possible design smells or external-library deprecations.','', 'The combined input contains 80,993 file-at-snapshot observations: Odoo 38,487, Jenkins 16,796 and Tomcat 25,710. Structural-rule observations span eligible annual snapshots from 2007 to 2024; each rule retains its actual coverage. API comparisons use 2014, 2019 and 2024 because those snapshots have explicit resolved-reference inventories. The two sparse Odoo contrasts remain descriptive under the fixed feasibility thresholds.','','## Adjusted results','','| Repository | Rule | Comparison rows | Flagged rows | Probability difference, pp (95% interval) | Mean count ratio (95% interval) |','|---|---|---:|---:|---|---|']
for rid in NAMES:
 for rule in RULES:
  binary=model(rid,rule,'binary');count=model(rid,rule,'count')
  def fmt(r,places):
   if r['status']!='fitted':return 'Descriptive only'
   if r.get('ci_low') is None:return f"{r['effect']:.{places}f}; interval unavailable"
   return f"{r['effect']:.{places}f} ({r['ci_low']:.{places}f}, {r['ci_high']:.{places}f})"
  lines.append(f"| {NAMES[rid]} | {RULES[rule]} | {binary['n']:,} | {binary['flagged_rows']:,} | {fmt(binary,2)} | {fmt(count,3)} |")
lines+=['','A percentage-point difference is an absolute difference in the probability of a recorded change; it is not a relative percentage increase. A count ratio of 1.223 means an estimated mean count 22.3% higher conditional on the modelled covariates. It does not mean each flagged file required 22.3% more work.','','## Why the raw differences are insufficient','','Flagged files are generally larger and already more active. For example, across the eligible Jenkins Long Method observations, flagged files have median size 420 lines versus 88 for unflagged files, and median prior change count 3 versus 1. Their raw following-year change proportions are 80.4% and 47.5%. After restricting comparison ranges and adjusting for size, prior activity and year, the probability-difference estimate is 0.69 percentage points (−3.25 to 4.63). The raw and adjusted populations differ because of the range restriction; the reduction cannot be attributed to adjustment alone. This illustrates why a correlation between annual totals or an unadjusted flagged/unflagged comparison would be misleading.','','## Comparison population and adjustment','','Long Method comparisons require a named definition; God Class comparisons require a class; API comparisons require at least one resolved source-API pair. Files lacking complete rule measurements are excluded rather than called unflagged. Each comparison retains years containing both groups and intersecting observed ranges of file size and prior activity. The models adjust for cubic splines in log(1 + PLOC) and log(1 + prior changes), plus year fixed effects.','', '| Repository | Rule | Eligible rows | Comparison rows | Excluded by comparison restriction |','|---|---|---:|---:|---:|']
for r in support:lines.append(f"| {NAMES[r['repository']]} | {RULES[r['rule']]} | {r['eligible_rows']:,} | {r['comparison_rows']:,} | {r['excluded_rows']:,} |")
lines+=['','The God Class restrictions are substantial, especially in Jenkins. The estimates therefore describe supported comparison subsets, not every file in each repository. Range overlap does not prove balanced multivariate covariates. Odoo has only seven flagged God Class lineages in the eligible data and five in the supported subset; the API contrast has only three flagged lineages in one year. Fitting those contrasts would not satisfy the predeclared minimums.','','## Statistical method','','The main probability-difference model is a linear probability regression. The count model is Poisson pseudo-maximum likelihood. Both use two-way clustered sandwich covariance by lineage and calendar year, with small-sample corrections and a t reference distribution whose degrees of freedom are the smaller cluster count minus one. Thus the API intervals use only two reference degrees of freedom. The [statsmodels two-group covariance documentation](https://www.statsmodels.org/v0.14.4/generated/statsmodels.stats.sandwich_covariance.cov_cluster_2groups.html) describes the covariance routine; the executed dependency version is pinned at 0.14.5. [The GLM documentation](https://www.statsmodels.org/stable/glm.html) documents the model framework.','', 'Robust covariance does not remove confounding, validate the detector or guarantee adequate small-cluster coverage. The count models have dispersion above one; sandwich uncertainty is used rather than an uncorrected Poisson variance. Coefficients are associations, not causal effects.','','## Sensitivity and model diagnostics','','Changing from raw timestamps to the ancestry clock barely changes the Odoo Long Method probability estimate (0.96 to 0.89 percentage points). Java event membership is unchanged. God Class count ratios remain approximately 1.224 in Jenkins and 1.140 in Tomcat when only modification events are counted. Excluding records with observed exits produces ratios 1.223 and 1.132, respectively, but this exclusion selects on future information and is only a diagnostic.','', 'Calendar-block omission retains positive Long Method point estimates for Odoo and Tomcat but can change the sign of the Jenkins estimate. The API probability estimates can change sign when a calendar block is omitted. These ranges are not confidence intervals.','', 'The linear probability models predict outside [0,1] for approximately 2–21% of their comparison observations. A post-fit, explicitly documented binomial-logit sensitivity therefore uses the same rows and covariate design. Its standardised probability differences are broadly similar. Clustered logistic intervals are unavailable for the Jenkins Long Method and God Class fits because the covariance calculation becomes non-finite at boundary predictions; their point estimates are retained without inferential claims. The logistic sensitivity is not substituted for the pre-specified main analysis.','','| Repository | Rule | Logistic probability difference, pp | 95% interval |','|---|---|---:|---|']
for r in logistic:
 interval=f"{r['ci_low']:.2f}, {r['ci_high']:.2f}" if r.get('ci_low') is not None else 'Unavailable'
 lines.append(f"| {NAMES[r['repository']]} | {RULES[r['rule']]} | {r.get('effect',float('nan')):.2f} | {interval} |")
lines+=['','## Thesis interpretation','','These results support a limited maintenance-related motivation: in two Java systems, the God Class detector identifies files associated with more frequent subsequent changes even after adjustment for observed size, prior activity and year. The data do not establish that those changes were bug fixes, costly, unnecessary or caused by the anti-pattern. They do not show that repairing the flagged classes would reduce change activity. Frequently modified central functionality may account for part of the remaining association.','', 'The Long Method and API findings do not support a general claim that all three anti-patterns independently increase maintenance burden. The strongest warranted thesis statement concerns selective investigation of frequently modified God Class candidates, alongside the descriptive persistence evidence. Controlled repair experiments must establish whether the proposed repairs are valid and useful.','', 'Remaining limitations include unreviewed detector decisions, best-effort semantic binding, edited moves that can split lineages, scope changes, large support exclusions, only three API years, overlapping follow-up windows and unmeasured file age, contributor experience, subsystem and prior confirmed defects. More recorded changes are not an ISO quality score.','','## Files and reproduction','','- `adjusted-change-probability.pdf`: main adjusted probability-difference figure.','- `adjusted-change-count.pdf`: secondary adjusted mean-count-ratio figure.','- `models.csv`, `support.csv`, `descriptive.csv`: effects, comparison populations and crude summaries.','- `sensitivity.csv`, `calendar-blocks.csv`, `logistic-sensitivity.csv`: robustness and model-form diagnostics.','- `analysis-input.csv.gz`, `input-seals.json`, `execution.json`: retained analysis inputs and provenance.','','```sh','python3 analysis/maintenance_associations/prepare_statistics_runtime.py --output /tmp/maintenance-statistics','python3 analysis/maintenance_associations/run_final_automated_analysis.py --packages /tmp/maintenance-statistics','python3 analysis/maintenance_associations/check_probability_model.py --packages /tmp/maintenance-statistics','python3 analysis/maintenance_associations/render_final_analysis.py --packages /tmp/maintenance-statistics','```','','The analysis refuses to overwrite its main results. A fresh checkout can use the default locations; alternate result directories are accepted by the fitting and probability-check scripts. Each figure shows 95% two-way clustered intervals. Panel scales differ; the count figure uses logarithmic horizontal axes.']
(OUT/'REPORT.md').write_text('\n'.join(lines)+'\n')
(OUT/'thesis-results.tex').write_text(r'''\paragraph{Anti-patterns and subsequent change activity.}
We examined whether files containing detected anti-patterns underwent more recorded mainline changes during the following 365 days. Comparisons were made within each repository, with adjustment for baseline file size, preceding-year change activity and calendar year. Files flagged for God Class had higher adjusted mean change counts in Jenkins (ratio 1.223; 95\% interval 1.132--1.321) and Apache Tomcat (1.142; 1.023--1.275). Similar estimates were obtained when counting modifications alone. These secondary count associations were not accompanied by clear evidence for the main binary endpoint: none of the seven estimable contrasts for the occurrence of any subsequent change passed the Holm-adjusted 5\% threshold. Odoo's God Class and obsolete-API contrasts were too sparse for the specified models. The API comparisons were further limited to three observation years.

The analysis used automated detector outputs without independent human validation. Its outcome was recorded change activity, rather than confirmed corrective maintenance or developer effort. The God Class results therefore support a maintenance-related association in the compared Java populations, but do not establish that the anti-pattern caused the changes or that repair would reduce their frequency. Unresolved bindings, imperfect file lineage, restricted comparison populations and unmeasured characteristics of the files remain possible sources of bias.
''')
print('Final report, thesis paragraph and readable PDF figures written.')
